from taf.analyzer.iperf_throughput.entry import clone_empty
import six
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class Calculator(object):
    @abstractmethod
    def calculate(self, data_collection):
        """pass"""


class PeakCalculator(Calculator):
    def calculate(self, data_collection):
        if data_collection.current_data.current > data_collection.current_data.result.peak:
            data_collection.current_data.result.peak = data_collection.current_data.current
        return data_collection.current_data.result.peak


class TotalCalculator(Calculator):
    def calculate(self, data_collection):
        old_total = data_collection.current_data.result.total or clone_empty(data_collection.current_data.current)
        new_total = data_collection.current_data.current + old_total
        new_count = data_collection.current_data.result.count + 1
        data_collection.current_data.result.total = new_total
        data_collection.current_data.result.count = new_count
        return data_collection.current_data.result.total


class MinimumCalculator(Calculator):
    def calculate(self, data_collection):
        if data_collection.current_data.current < data_collection.current_data.result.minimum:
            data_collection.current_data.result.minimum = data_collection.current_data.current
        return data_collection.current_data.result.minimum
